#[test]
fn climate_and_biomes_match() {
  let f = fixture();
  let t = terrain(&f);
  let mut s = t.scratch();

  for case in f["climate"].as_array().unwrap() {
    let (qx, qy, qz) = (
      case["qx"].as_i64().unwrap() as i32,
      case["qy"].as_i64().unwrap() as i32,
      case["qz"].as_i64().unwrap() as i32,
    );
    let want: Vec<i64> =
      case["target"].as_array().unwrap().iter().map(|v| v.as_i64().unwrap()).collect();
    let got = t.climate(&mut s, qx << 2, qy << 2, qz << 2);
    assert_eq!(got.to_vec(), want, "climate at quart ({qx}, {qy}, {qz})");

    // Ties between equally near points may be broken differently, so compare
    // how near it is.
    let (_, fitness) = t.nearest_biome(got);
    assert_eq!(
      fitness,
      case["fitness"].as_i64().unwrap(),
      "nearest biome fitness at ({qx}, {qy}, {qz})"
    );
  }
}

/// How far the prediction is from the game's own surface heights
/// (`getBaseHeight`, caves included).
#[test]
fn surface_heights_match_vanilla() {
  let f = fixture();
  let t = terrain(&f);
  let mut s = t.scratch();

  let mut errors = Vec::new();
  for case in f["vanilla_heights"].as_array().unwrap() {
    let (x, z) = (case["x"].as_i64().unwrap() as i32, case["z"].as_i64().unwrap() as i32);
    let want = case["h"].as_i64().unwrap() as i32;
    let got = t.surface_top(&mut s, x, z).unwrap();
    errors.push((got - want).abs());
  }
  errors.sort();
  let n = errors.len();
  let mean = errors.iter().sum::<i32>() as f64 / n as f64;
  println!(
    "surface error vs vanilla over {n} columns: mean {mean:.3}, median {}, p90 {}, p99 {}, max {}",
    errors[n / 2],
    errors[n * 9 / 10],
    errors[n * 99 / 100],
    errors[n - 1]
  );
  let exact = errors.iter().filter(|&&e| e == 0).count();
  println!("exact: {exact} of {n}");
  assert!(mean < 0.3, "mean surface error {mean}");
}

/// Not a check: prints how fast the port is. `cargo test --release --test
/// oracle bench -- --ignored --nocapture`
#[test]
#[ignore]
fn bench_tiles() {
  use look_native::engine::Engine;
  use std::time::Instant;

  let f = fixture();
  let t = terrain(&f);
  let mut s = t.scratch();

  for level in [1u32, 2, 4, 7] {
    let n = 40;
    let start = Instant::now();
    for i in 0..n {
      t.sample_tile(&mut s, level, i * 3 - 60, i * 5 - 90);
    }
    let per_tile = start.elapsed().as_secs_f64() / n as f64;
    println!(
      "level {level}: {:.2} ms/tile, {:.1} us/column (one thread)",
      per_tile * 1e3,
      per_tile * 1e6 / 256.0
    );
  }

  // Where the time goes, per column.
  let n = 4000;
  let start = Instant::now();
  let mut tops = Vec::new();
  for i in 0..n {
    tops.push(t.surface_top(&mut s, (i * 37) % 9000 - 4500, (i * 91) % 9000 - 4500).unwrap_or(64));
  }
  let surface = start.elapsed().as_secs_f64() / n as f64;
  let start = Instant::now();
  let mut climates = Vec::new();
  for i in 0..n {
    climates.push(t.climate(
      &mut s,
      ((i * 37) % 9000 - 4500) & !3,
      tops[i as usize] & !3,
      ((i * 91) % 9000 - 4500) & !3,
    ));
  }
  let climate = start.elapsed().as_secs_f64() / n as f64;
  let start = Instant::now();
  let mut sum = 0;
  for c in &climates {
    sum += t.nearest_biome(*c).0;
  }
  let nearest = start.elapsed().as_secs_f64() / n as f64;
  println!(
    "per column: surface {:.1} us, climate {:.1} us, nearest biome {:.1} us ({sum})",
    surface * 1e6,
    climate * 1e6,
    nearest * 1e6
  );

  // Many tiles over all threads, as the mod would request them.
  let threads =
    std::thread::available_parallelism().map(|n| n.get()).unwrap_or(2).saturating_sub(2).max(1);
  let engine = Engine::new(terrain(&f), 100, threads);
  engine.set_camera(0, 0);
  let mut count = 0;
  for level in 1..8u32 {
    for sx in -18..=18 {
      for sz in -18..=18 {
        engine.request(level, sx, sz);
        count += 1;
      }
    }
  }
  let start = Instant::now();
  let mut keys = vec![0u64; 4096];
  let mut done = 0;
  while done < count {
    done += engine.poll(&mut keys);
    std::thread::sleep(std::time::Duration::from_millis(5));
  }
  let secs = start.elapsed().as_secs_f64();
  println!(
    "{count} tiles ({} columns) on {threads} threads: {secs:.2} s ({:.0} tiles/s)",
    count * 256,
    count as f64 / secs
  );
}

#[test]
fn biome_tree_matches_brute_force() {
  use look_native::biome::BiomeIndex;

  let f = fixture();
  let index = BiomeIndex::from_json(&f["config"]["biomes"]).unwrap();

  // Targets spread over (and a bit past) the ranges biomes are defined for.
  let mut state = 0x1234_5678_9ABC_DEF0u64;
  let mut next = |range: i64| {
    state ^= state << 13;
    state ^= state >> 7;
    state ^= state << 17;
    (state % (range as u64 * 2 + 1)) as i64 - range
  };
  for i in 0..5000 {
    let target = [next(12000), next(12000), next(12000), next(12000), next(12000), next(12000)];
    let (_, tree) = index.nearest_index(target);
    let (_, brute) = index.nearest_index_brute_force(target);
    assert_eq!(tree, brute, "target #{i} {target:?}");
  }
}

#[test]
fn tile_keys_round_trip() {
  use look_native::engine::{pack_key, unpack_key};

  for level in 0..8 {
    for (sx, sz) in [(0, 0), (-1, 1), (1, -1), (-2_097_152, 2_097_151), (123_456, -654_321)] {
      assert_eq!(unpack_key(pack_key(level, sx, sz)), (level, sx, sz));
    }
  }
}

#[test]
fn engine_builds_the_same_bricks_as_direct_sampling() {
  use look_native::{
    engine::Engine,
    terrain::{Ids, BRICK_VOXELS},
  };
  use std::time::{Duration, Instant};

  let f = fixture();
  let direct = terrain(&f);
  let mut s = direct.scratch();
  let engine = Engine::new(terrain(&f), 100, 4);

  let mut ids = [0i32; Ids::LEN];
  for (i, id) in ids.iter_mut().enumerate() {
    *id = 10 + i as i32;
  }
  let ids = Ids::from_slice(&ids).unwrap();
  engine.set_ids(ids);
  engine.set_camera(0, 0);

  // Negative coordinates on purpose, and requesting everything twice must not
  // queue it twice.
  let tiles: Vec<(u32, i32, i32)> =
    (-3..=3).flat_map(|x| (-3..=3).map(move |z| (3, x, z))).collect();
  for &(level, sx, sz) in &tiles {
    assert!(engine.request(level, sx, sz));
  }
  for &(level, sx, sz) in &tiles {
    assert!(!engine.request(level, sx, sz), "second request of ({sx}, {sz}) was queued again");
  }

  let mut brick = [0u16; BRICK_VOXELS];
  assert_eq!(engine.fetch(3, 99, 0, 99, &mut brick), None, "a tile nobody asked for has no data");

  let mut keys = vec![0u64; 16];
  let mut done = 0;
  let start = Instant::now();
  while done < tiles.len() {
    done += engine.poll(&mut keys);
    assert!(
      start.elapsed() < Duration::from_secs(30),
      "timed out with {done} of {} tiles",
      tiles.len()
    );
    std::thread::sleep(Duration::from_millis(2));
  }
  assert_eq!(engine.poll(&mut keys), 0, "each tile is reported once");

  for &(level, sx, sz) in &tiles {
    let tile = direct.sample_tile(&mut s, level, sx, sz);
    for sy in -1..=1 {
      let mut want = [0u16; BRICK_VOXELS];
      let want_solid = tile.fill_brick(level, sy, &direct.params, &ids, &mut want);
      let got_solid = engine.fetch(level, sx, sy, sz, &mut brick).expect("finished tile");
      assert_eq!(got_solid, want_solid, "solid count of ({sx}, {sy}, {sz})");
      assert_eq!(brick[..], want[..], "brick ({sx}, {sy}, {sz})");
    }
  }

  let (queued, kept, computed) = engine.stats();
  assert_eq!((queued, kept, computed), (0, tiles.len(), tiles.len() as u64));
  drop(engine); // joins the workers; hangs here if they do not stop
}

#[test]
fn engine_drops_tiles_that_are_out_of_range() {
  use look_native::engine::Engine;
  use std::time::Duration;

  let f = fixture();
  // Only tiles within 2 sections of the camera are wanted, and none of them are
  // close to (50, 50).
  let engine = Engine::new(terrain(&f), 2, 2);
  engine.set_camera(0, 0);
  assert!(engine.request(1, 50, 50));
  std::thread::sleep(Duration::from_millis(200));

  let mut keys = vec![0u64; 4];
  assert_eq!(engine.poll(&mut keys), 0, "an out of range tile is skipped, not computed");
  assert_eq!(engine.stats().0, 0, "and it is no longer pending, so it can be asked for again");
  assert!(engine.request(1, 50, 50));
}

#[test]
fn heightfield_tiles_are_handed_over_once() {
  use look_native::{
    engine::{Engine, HF_FLAG},
    terrain::HF_BYTES,
  };
  use std::time::{Duration, Instant};

  let f = fixture();
  let engine = Engine::new(terrain(&f), 24, 2);
  engine.set_camera(0, 0);
  assert!(engine.request_heightfield(1, 3, 4));
  assert!(!engine.request_heightfield(1, 3, 4), "already queued");

  let mut keys = vec![0u64; 4];
  let start = Instant::now();
  let mut n = 0;
  while n == 0 && start.elapsed() < Duration::from_secs(20) {
    std::thread::sleep(Duration::from_millis(20));
    n = engine.poll(&mut keys);
  }
  assert_eq!(n, 1);
  assert_ne!(keys[0] & HF_FLAG, 0, "the key says it is a heightfield tile");

  let mut out = [0u8; HF_BYTES];
  assert!(engine.take_heightfield(1, 3, 4, &mut out));
  assert!(!engine.take_heightfield(1, 3, 4, &mut out), "a tile is taken only once");
  assert!(engine.request_heightfield(1, 3, 4), "and can be asked for again");
}
